manifest={'manifest_version':3,'name':'Bullets of Fury: Field Manual','version':'1.0.0','description':'Offline pilot dossiers, arsenal, boss tactics and your own field notes.','icons':{str(n):f'art/icon{n}.png' for n in [16,32,48,128]},'action':{'default_title':'Open BOF Field Manual','default_popup':'popup.html','default_icon':{str(n):f'art/icon{n}.png' for n in [16,32]}},'content_security_policy':{'extension_pages':"script-src 'self'; object-src 'self'"}}
