save('popup.html','<!doctype html><html lang="en"><meta charset="utf-8"><title>BOF Field Manual</title><link rel="stylesheet" href="style.css"><body class="popup"><img class="logo" src="art/logo.png" alt="Bullets of Fury"><h1>FIELD MANUAL</h1><p>Your next life starts with a better plan.</p><button id="open">OPEN THE FULL GUIDE ↗</button><p class="fine">Offline. No tracking. No access to your browsing.</p><script src="popup.js"></script></body></html>')
save('popup.js',"document.querySelector('#open').addEventListener('click',()=>chrome.tabs.create({url:chrome.runtime.getURL('guide.html')}));")
save('guide.html','''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BOF • Field Manual</title><link rel="stylesheet" href="style.css"></head><body><header><a href="#cover" aria-label="Field manual cover"><img class="logo" src="art/logo.png" alt="Bullets of Fury"></a><span>FIELD MANUAL / VOL. 01</span></header><div class="layout"><aside><label for="search">FIND YOUR EDGE</label><input id="search" type="search" placeholder="Pilot, weapon, boss…"><nav id="nav" aria-label="Chapters"></nav><p class="fine">October 12, 2026 edition<br>Current base-game roster. Local notes stay on this device.</p></aside><main><section class="cover" id="cover"><div><p class="eyebrow">THE OFFLINE SURVIVAL GUIDE</p><h1>KNOW YOUR ENEMY.<br>OWN THE SKY.</h1><p>Read the tell. Commit to the gap. Punish the recovery.</p><a class="button" href="#survival">GET COMBAT READY ↓</a></div><img src="art/icon512.png" alt="Jet and tactical field manual insignia"></section><div class="toolbar"><label for="difficulty">Difficulty briefing</label><select id="difficulty"></select><button id="saved">★ Saved only</button><span id="count" role="status"></span></div><div id="briefing"></div><div id="content"></div><p id="empty" hidden>No matching dossiers. Try a shorter search.</p><footer>Original BOF artwork and game data. Tactics are advice, not guaranteed clears. Configure controls in the game. Overdrive has a separate combat ruleset; base-game numbers here do not apply to it.</footer></main></div><script src="data.js"></script><script src="guide.js"></script></body></html>''')
save('style.css','''@font-face{font-family:Fury;src:url(art/BlackOpsOne.ttf)}:root{--orange:#ffae32;--red:#f44535;--ink:#080f18;--panel:#12202c;--line:#344a55;--text:#ecf2e9}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:110px}body{margin:0;background:var(--ink);color:var(--text);font:17px/1.6 system-ui,sans-serif}header{display:flex;justify-content:space-between;align-items:center;padding:12px 4%;background:#101b23;border-bottom:4px solid var(--orange);position:sticky;top:0;z-index:2}header .logo{width:235px}header span,.eyebrow,label{font-weight:800;letter-spacing:2px;color:var(--orange);font-size:12px}.layout{display:grid;grid-template-columns:245px minmax(0,1fr);max-width:1550px;margin:auto}aside{padding:28px 22px;position:sticky;top:100px;height:calc(100vh - 100px);overflow:auto;border-right:1px solid var(--line)}input,select,textarea,button,.button{font:inherit;color:var(--text);background:var(--panel);border:1px solid #69808a;border-radius:3px;padding:10px}input{width:100%;margin:10px 0 20px}nav a{display:block;padding:10px 0;color:var(--text);text-decoration:none;border-bottom:1px solid var(--line)}nav a:hover,a:hover{color:var(--orange)}main{padding:30px;min-width:0}h1,h2,h3{font-family:Fury,system-ui;line-height:1.15;font-weight:400}h1{font-size:clamp(35px,4.2vw,66px);margin:14px 0;color:var(--orange)}h2{font-size:34px;margin-top:50px;border-bottom:4px solid var(--red);padding-bottom:12px}h3{font-size:25px;margin:10px 0}.cover{display:grid;grid-template-columns:1fr 32%;gap:30px;align-items:center;padding:30px;background:linear-gradient(135deg,#1e3440,#151b20);border:1px solid #51626b;box-shadow:9px 9px 0 #000}.cover img{width:100%;transform:rotate(3deg)}.button{display:inline-block;text-decoration:none;background:#a32920;font-weight:800}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:28px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px}.card{background:var(--panel);border:1px solid var(--line);border-top:4px solid var(--accent,var(--orange));padding:22px;scroll-margin-top:120px}.card img{width:100%;max-height:210px;object-fit:contain;image-rendering:pixelated;background:#08131c}.card .tag{font-size:12px;letter-spacing:1.8px;color:var(--orange);font-weight:800}.card p{margin:12px 0}.card button{font-size:14px;cursor:pointer}.card textarea{width:100%;min-height:85px;margin-top:8px;font-size:14px}.card details{margin-top:15px}.card summary{cursor:pointer;color:#b8d8db}.fine,footer{font-size:12px;color:#a7bac4}footer{margin-top:45px;padding:25px 0;border-top:1px solid var(--line)}#briefing{padding:18px;background:#172a35;border-left:5px solid var(--orange)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--orange);outline-offset:3px}button[aria-pressed=true]{background:#725318}.popup{width:350px;padding:24px;text-align:center}.popup .logo{width:100%}.popup h1{font-size:32px}.popup button{background:#a32920;width:100%}@media(max-width:850px){.layout{display:block}aside{position:static;height:auto;border-right:0}nav{display:flex;gap:15px;flex-wrap:wrap}aside .fine{display:none}main{padding:18px}.cover{padding:22px;grid-template-columns:1fr}.cover img{display:none}header span{display:none}header .logo{width:190px}.grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{header,aside,.toolbar,button,details{display:none}.layout{display:block}body,.card{background:white;color:black}.cover{box-shadow:none}.card{break-inside:avoid}h1{color:black}}''')
save('guide.js','''const $=s=>document.querySelector(s);let savedOnly=false;let saved={},notes={};try{saved=JSON.parse(localStorage.getItem('bof-manual-saved')||'{}');notes=JSON.parse(localStorage.getItem('bof-manual-notes')||'{}')}catch{}const chapters=[['survival','Flight school'],['pilots','Pilot dossiers'],['arsenal','Arsenal'],['campaign','Stage intelligence'],['bosses','Boss survival'],['extras','Modes & systems']];const entries=[];function add(ch,id,title,tag,body,art,accent){entries.push({ch,id,title,tag,body,art,accent})}
add('survival','movement','MOVE WITH A PURPOSE','SURVIVAL', 'Keep a route open before firing. Short taps preserve room; long sweeps are for crossing a committed lane. Avoid camping in a corner unless an attack specifically rewards the edge.');
add('survival','warnings','READ THE TELL','DODGE PLAN','Watch the warning origin and direction. Let an aimed attack commit, then leave its lane. Chasing warnings around the arena spends your escape space before the shot arrives.');
add('survival','resources','SPEND TO SURVIVE','ROLL / SOMERSAULT / SPECIAL','Watch the solid cooldown bars. Save a maneuver for the next dangerous crossing. Use a special or missile before a trap closes rather than after damage. Customize your bindings in Settings; this manual does not assume default keys.');
for(const p of MANUAL.pilots){const s=MANUAL.specials[p.key];add('pilots',p.key,p.name,p.role,s.name+': '+s.desc+' '+(p.locked?'Cole starts locked; his session unlock is also preserved in campaign saves.':'')+' Learn your ship’s movement before increasing difficulty.',p.art,p.tint)}
const advice=['Reliable forward pressure. Keep firing while moving through the open lane.','Covers a wider frontage. Useful when enemies arrive from multiple columns.','A distinct weapon from your limited missile stock. Choose your line before firing.','Align with the target during recovery. Break alignment immediately when a warning claims your lane.','Close-range commitment needs a clear escape route. Do not trade survival for sustained contact.','Use the weapon’s visible path to judge reach. Continue moving while it works.','Area coverage does not replace watching incoming rounds.','Sustained fire rewards a stable lane. Check your firing line after each pickup.','Watch nearby threats while maintaining pressure.'];MANUAL.weapons.forEach((w,i)=>add('arsenal','weapon-'+i,w,'WEAPON '+(i+1),advice[i]));
add('arsenal','maverick-rule','MAVERICK: KNOW THE DIFFERENCE','FIXED HOMING / HELIX','Maverick’s homing lasers stay at level 1 and do not receive weapon upgrades, elemental changes or wind upgrades. His Laser Beam and Helix progression are separate systems.');
const tips=['Keep an exit around the dam arena; avoid being pinned by ground fire while following airborne targets.','Watch the warning lanes against the bright lava. Do not let the scenery hide incoming fire.','Use deliberate taps. Contrast the enemy rounds against the pale ground before committing to a long crossing.','The lost airbase is a moving battlefield. Watch the ship’s weapon sockets and the regenerating energy cores.','Space brings different weapon systems. The Stage 5 gate leads to the bonus Stage 9 route.','Expect coordinated air threats. Watch individual rebel health bars and avoid aligning with several guns at once.','Track rounds against the toxic background. Keep a clean lateral route through crowded sections.','Final-boss changes demand a fresh read of the arena. Treat each transformation as a new attack book.','This is a bonus route, not a ninth mandatory campaign level. Enter through the Stage 5 gate.'];
for(const s of MANUAL.stages)add('campaign','stage-'+s.n,s.name+' · '+s.sub,s.bonus?'BONUS ROUTE':'CAMPAIGN',tips[s.n-1]+' Current main boss identifier: '+s.boss+'.');
add('campaign','stage-x','STAGE X · COASTAL CITY','EXTRA ENCOUNTER','Harrier and rebel encounters use different boss displays. Read the active opponent’s bar rather than expecting every fight to share one screen-wide meter.');
add('bosses','cross','THE ROTATING CROSS','STAGES 4 / 5 / 8','Four rays rotate in pulses. Stay in an open sector while the rays are hot; cross the former beam lane after it dissolves. The next preview shows where the rotor continues. Do not try to outrun a live beam around its source. The Hard Corps controller completes six pulses in one revolution.');
add('bosses','cores','STORM SOVEREIGN','STAGE 4 BOSS','Destroy energy cores while respecting the central weapon. Lightning charge-up signals core revival: reacquire the reappearing targets. Core revival interrupts the custom attack sequence. Keep an escape route for the committed left/right lightning relay.');
add('bosses','tempest','TEMPEST ECLIPSE','STAGE 5 MINIBOSS','Read relocation, settling, then the committed paired lances. Destroying cannons removes their owned warnings, rays and shots. Losing both cannons changes the fight to bay flak; reassess instead of assuming it is harmless.');
add('bosses','siege','ECLIPSE SIEGE BOMBER','STAGE 6 MINIBOSS','Find the one open flak column before committing. Moving gun passes and paired lances follow their warnings. Use the recovery and relocation windows to reposition and attack the surviving modules.');
add('bosses','herald','HERALD','STAGE 8 MINIBOSS','Learn cannon, lance and salvo patterns first. Every fourth attack adds the wing-driven cross. Each wing owns two opposing rays: breaking a wing disarms those rays. Falling broken parts remain solid artwork; fading discharge is a separate effect.');
add('bosses','rift','EVIL CHROMIUM RIFT','FINAL BOSS / HAMMER','The raised hand is your cue to leave the center. Move toward the screen edge before the void pull becomes dangerous. Keep enough room to avoid chromium lightning while resisting the pull. Re-enter deliberately when the rift ends.');
add('bosses','rook','ROOKHOOK','REBEL FIGHTERS','Respect the grapple tell and leave its line before it connects. A hooked jet can be pulled and thrown toward the screen edge. Avoid stacking against the edge while the hook attack is being prepared.');
add('extras','difficulty','BUILD YOUR RUN','DIFFICULTY','Easy gives more starting resources and slower enemy fire. Normal teaches the full cadence. Hard and Furious tighten resources and timing. Insanity is an achievement-shop unlock. The briefing above shows the current starting stocks and continue limits.');
add('extras','modes','CAMPAIGN & OVERDRIVE','MODE GUIDE','The base campaign ends at Stage 8; Stage 9 is a Stage 5 bonus route. Overdrive is launched separately with PLAY_OVERDRIVE.bat and uses its own combat rules. Boss Rush and Time Attack cards are not currently playable; do not treat a revealed card as an available mode.');
function persist(){try{localStorage.setItem('bof-manual-saved',JSON.stringify(saved));localStorage.setItem('bof-manual-notes',JSON.stringify(notes))}catch{$('#count').textContent='Local storage is unavailable.'}}
for(const [id,title] of chapters){const a=document.createElement('a');a.href='#'+id;a.textContent=title;$('#nav').append(a)}
for(const [id,d] of Object.entries(MANUAL.difficulties)){const o=document.createElement('option');o.value=id;o.textContent=d.name;$('#difficulty').append(o)}$('#difficulty').value='normal';
function briefing(){const d=MANUAL.difficulties[$('#difficulty').value];$('#briefing').textContent=d.name+' — '+d.startLives+' starting lives · '+d.startBombs+' starting missiles · '+(d.continues<0?'Unlimited':d.continues)+' continues. Enemy projectile speed ×'+d.ebSpeed+'; fire-rate scale ×'+d.eFire+'. These are configuration scales, not measured survival odds.'}
function render(){const term=$('#search').value.toLowerCase().trim();$('#content').replaceChildren();let count=0;for(const [ch,title] of chapters){const es=entries.filter(e=>e.ch===ch&&(!savedOnly||saved[e.id])&&(e.title+' '+e.tag+' '+e.body+' '+(notes[e.id]||'')).toLowerCase().includes(term));if(!es.length)continue;const sec=document.createElement('section');sec.id=ch;const h=document.createElement('h2');h.textContent=title;sec.append(h);const grid=document.createElement('div');grid.className='grid';for(const e of es){count++;const c=document.createElement('article');c.className='card';c.id=e.id;if(e.accent)c.style.setProperty('--accent',e.accent);if(e.art){const im=document.createElement('img');im.src=e.art;im.alt=e.title+' portrait';im.loading='lazy';c.append(im)}for(const [tag,text,cls] of [['div',e.tag,'tag'],['h3',e.title,''],['p',e.body,'']]){const n=document.createElement(tag);n.textContent=text;n.className=cls;c.append(n)}const b=document.createElement('button');b.textContent=saved[e.id]?'★ SAVED':'☆ SAVE DOSSIER';b.setAttribute('aria-pressed',!!saved[e.id]);b.onclick=()=>{saved[e.id]=!saved[e.id];persist();render()};c.append(b);const det=document.createElement('details');const sum=document.createElement('summary');sum.textContent='Your field notes';const ta=document.createElement('textarea');ta.setAttribute('aria-label','Notes for '+e.title);ta.value=notes[e.id]||'';ta.maxLength=5000;ta.oninput=()=>{notes[e.id]=ta.value;persist()};det.append(sum,ta);c.append(det);grid.append(c)}sec.append(grid);$('#content').append(sec)}$('#empty').hidden=!!count;$('#count').textContent=count+' dossiers'}$('#search').oninput=render;$('#difficulty').onchange=briefing;$('#saved').onclick=()=>{savedOnly=!savedOnly;$('#saved').setAttribute('aria-pressed',savedOnly);render()};briefing();render();''')
save('README.md','''# Bullets of Fury: Field Manual\n\nOffline Manifest V3 extension. No host permissions, tracking, external code or network requests. Notes/bookmarks use this extension’s local storage.\n\n## Install in Chrome or Edge\n1. Extract the ZIP into a permanent folder.\n2. Open chrome://extensions (Edge: edge://extensions).\n3. Enable Developer mode. Choose Load unpacked.\n4. Select the folder containing manifest.json. Pin Field Manual; click its icon, then OPEN THE FULL GUIDE.\n\nThis ZIP is an unpacked extension, not a Chrome Web Store listing. Firefox users can open guide.html as a standalone manual; this package is not a Firefox add-on.\n\nEdition: October 12, 2026. Pilot, special, stage, weapon and difficulty data exported from current runtime. Combat advice derived from Hard Corps encounter documentation and current game systems. Base-game rules; Overdrive rules are separate. Original BOF art, BlackOpsOne font (notice in art), generated icon. No guaranteed survival claims.\n\nManifest documentation: https://developer.chrome.com/docs/extensions/reference/manifest\n''')
