js=js.replace("function persist(){", "for(const f of MANUAL.fights){if(entries.some(e=>e.title===f.name))continue;add('bosses','fight-'+f.stage+'-'+f.role,f.name,'STAGE '+f.stage+' / '+(f.role==='mini'?'MINIBOSS':'BOSS'),'Read the warning before committing to a firing lane. Attack during recovery, keep a maneuver available for crossing, and reassess the attack pattern after a module breaks. This roster entry identifies the current encounter; specific attack timings are not yet documented here.')}function persist(){")
save('guide.js',js)
